new A.CD(q,$,$,$,$,$,$,q,$,$,$,$,n,q,$,$,$,$,new A.lz(q,new Float32Array(64),new Int32Array(A.bQ(A.c([0,0],p))),A.c([],o)),n,B.aj).kq("#version 300 es\n// Skinning vert-shader ES3 //////////\n// must insert before vertex shader\n\n#define ENABLE_SKINNING\n\nlayout(location = 0) in highp vec3 inVertex;\nlayout(location = 4) in mediump vec4 inBoneIndex; // Back to vec4 for buffer compatibility\nlayout(location = 5) in mediump vec4 inBoneWeight;\n\n// skinning mesh part: bone\nuniform mediump int BoneCount;\nuniform highp mat4 BoneMatrixArray[32];\n\n#ifdef ENABLE_NORMAL\nlayout(location = 2) in mediump vec3 inNormal;\nvoid ComputeSkinningVertex(out highp vec4 objVert, out mediump vec3 objNormal)\n#else\nvoid ComputeSkinningVertex(out highp vec4 objVert)\n#endif // ENABLE_NORMAL\n{\n    highp vec4 srcVert = vec4(inVertex, 1.0);\n    \n    // Cast vec4 to ivec4 for lookup\n    ivec4 boneIndex = ivec4(inBoneIndex + 0.5);\n\n    objVert = BoneMatrixArray[boneIndex.x] * srcVert * inBoneWeight.x;\n#ifdef ENABLE_NORMAL\n    objNormal = mat3(BoneMatrixArray[boneIndex.x]) * inNormal * inBoneWeight.x;\n#endif // ENABLE_NORMAL\n\n    if (BoneCount > 1)\n    {\n        objVert += BoneMatrixArray[boneIndex.y] * srcVert * inBoneWeight.y;\n#ifdef ENABLE_NORMAL\n        objNormal += mat3(BoneMatrixArray[boneIndex.y]) * inNormal * inBoneWeight.y;\n#endif // ENABLE_NORMAL\n        if (BoneCount > 2)\n        {\n            objVert += BoneMatrixArray[boneIndex.z] * srcVert * inBoneWeight.z;\n#ifdef ENABLE_NORMAL\n            objNormal += mat3(BoneMatrixArray[boneIndex.z]) * inNormal * inBoneWeight.z;\n#endif // ENABLE_NORMAL\n            if (BoneCount > 3)\n            {\n                objVert += BoneMatrixArray[boneIndex.w] * srcVert * inBoneWeight.w;\n#ifdef ENABLE_NORMAL\n                objNormal += mat3(BoneMatrixArray[boneIndex.w]) * inNormal * inBoneWeight.w;\n#endif // ENABLE_NORMAL\n            }\n        }\n    }\n#ifdef ENABLE_NORMAL\n    objNormal = normalize(objNormal);\n#endif // ENABLE_NORMAL\n}\n\n#version 300 es\n// Water vert-shader ES3 //////////\n#ifndef ENABLE_SKINNING\nlayout(location = 0) in highp vec3 inVertex;\t\t// vertex-data\n#endif // ENABLE_SKINNING\n\n// layout(location = 1) in lowp vec4 inColor;\t\t// for water-color as fog in water\nlayout(location = 3) in mediump vec2 inTexCoord;\n\nuniform lowp vec4 uColor;\n\n// eye-space for camera-viewer\nuniform highp mat4 ModelviewProjection;\n// object-space (same as world-space here)\nuniform mediump vec3 uEyePos;\t// eye as camera origin\n\nuniform mediump vec4 BumpTranslateScale0;\t// xy: translate, zw: scale\nuniform mediump vec4 BumpTranslateScale1;\t// xy: translate, zw: scale\n\n// tangent-space by plane\nuniform lowp vec3 AxisTangent;\t\t// as X-axis\nuniform lowp vec3 AxisBinormal;\t\t// as Y-axis\nuniform lowp vec3 AxisNormal;\t\t// as Z-axis\n\n// shader variable: from vert to frag\nout mediump vec2 BumpCoord0;\nout mediump vec2 BumpCoord1;\nout highp vec3 eyeToObj;\t\t// interpolate from vert to frag: must be highp in iPad3 \nout highp float eyeToObjDist;\nout highp vec3 ObjectspaceV;    // Object space Vertex\n\nout lowp vec4 DestinationColor;\n\n#ifdef ENABLE_FOG\nout highp float fogDist;   // distance: eye to obj-vertex\n#endif // ENABLE_FOG\n\nvoid main(void)\n{\n\tDestinationColor = uColor;\n\t\n\thighp vec4 objVert = vec4(inVertex, 1.0);\n#ifdef ENABLE_SKINNING\n\tif (BoneCount > 0)\n\t{\n\t\tComputeSkinningVertex(objVert);\n\t}\n#endif // ENABLE_SKINNING\n\n#if defined(ENABLE_SHADOW_MAP) || defined(ENABLE_SHADOW_CSM)\n    ComputeShadowPosition(objVert.xyz, AxisNormal);\n#endif // ENABLE_SHADOW_MAP or ENABLE_SHADOW_CSM\n\n    gl_Position = ModelviewProjection * objVert;\t// pre-compute Projection * Modelview\n\t\n\t// Scale and translate texture coordinates used to sample the normal map - section 2.2 of white paper\n\tBumpCoord0 = (inTexCoord * BumpTranslateScale0.zw) + BumpTranslateScale0.xy;\n\tBumpCoord1 = (inTexCoord * BumpTranslateScale1.zw) + BumpTranslateScale1.xy;\n\t\n\t// The water to eye vector is used to calculate the Fresnel term\n\t// and to fade out perturbations based on distance from the viewer\n\teyeToObj = uEyePos - objVert.xyz;\n\teyeToObjDist = length(eyeToObj);\n\t\n\tObjectspaceV = objVert.xyz;\n\n\t// tangent-space\n\teyeToObj = vec3(dot(AxisTangent, eyeToObj), dot(AxisBinormal, eyeToObj), dot(AxisNormal, eyeToObj));\n\n#ifdef ENABLE_FOG\n    fogDist = eyeToObjDist;\n#endif // ENABLE_FOG\n}\n\n","#define ENABLE_POINT_LIGHTS \n#version 300 es\nprecision mediump float;\n// Water frag-shader ES3 //////////\n\n// water distortion (noise effect)\nin mediump vec2 BumpCoord0;\nin mediump vec2 BumpCoord1;\nin highp vec3 eyeToObj;\t\t// interpolate from vert to frag: must be highp in iPad3 \nin highp float eyeToObjDist;\nin highp vec3 ObjectspaceV;    // Object space Vertex\nuniform mediump vec3 uInvObjScale;\n\nuniform mediump float WaveDistortion;\n\nuniform sampler2D SamplerDiffuse;\t// GL_TEXTURE0: diffuse as reflection\nuniform sampler2D NormalTex;\t\t// GL_TEXTURE1: normalmap (Normal map uses z-axis major)\nuniform sampler2D RefractionTex;\t// GL_TEXTURE2: refraction\nuniform mediump vec4 CameraViewport; // xyzw for (x,y,width,height)\n\n// uniform lowp vec4 uColor;\n\n// shade lit/unlit functions\nlowp vec4 ShadeLit(in lowp vec4 texDiffuse)\n{\n\treturn texDiffuse;\n}\n\nlowp vec4 ShadeUnlit(in lowp vec4 texDiffuse)\n{\n\treturn vec4(texDiffuse.rgb * 0.7, 1.0);\n}\n\n// output color\nout vec4 fragColor;\n\n// blend reflection and refraction\nlowp vec4 BlendReflectionRefraction(in lowp vec3 vAccumulatedNormal, in lowp vec3 eyeToObjNormal)\n{\n\t// Calculate the Fresnel term to determine amount of reflection for each fragment\n\tmediump float fresnel = clamp(dot(eyeToObjNormal, vAccumulatedNormal), 0.0, 1.0);\n\tfresnel = 1.0 - fresnel;\n\tfresnel = pow(fresnel, 5.0);\n\tfresnel = (0.9 * fresnel) + 0.1;\t// R(0)-1 = ~0.98 , R(0)= ~0.02\n\t\n\t// Calculate the tex coords of the fragment (using it's position on the screen), normal map is z-axis major.\n\tmediump vec2 vTexCoord = (gl_FragCoord.xy - CameraViewport.xy) / CameraViewport.zw;\n\n\t// Divide by eyeToObjDist to scale down the distortion\n\t// of fragments based on their distance from the camera \n\tvTexCoord.xy -= vAccumulatedNormal.xy * (WaveDistortion / eyeToObjDist);\n\n\t// reflection, refraction\n\tlowp vec4 ReflectionColor = texture(SamplerDiffuse, vTexCoord);\n\tlowp vec4 RefractionColor = texture(RefractionTex, vTexCoord);\n\t// Blend reflection and refraction\n\tlowp vec4 result;\n\tresult = mix(RefractionColor, ReflectionColor, fresnel);\n//\tresult = mix(ReflectionColor, RefractionColor, 0.4);\t// Constant mix\n//\tresult = RefractionColor;\t\t\t// ReflectionColor, RefractionColor only\n\treturn result;\n}\n\n#ifdef ENABLE_WATER_SPECULAR\n// tangent-space by light\nuniform lowp vec3 LightDiffuse;\t\t// diffuse of light\nuniform mediump vec3 uLightDir;\t\t// parallel light\n#endif // ENABLE_WATER_SPECULAR\n\n#ifdef ENABLE_FOG\nlowp vec4 ApplyFog(in lowp vec4 texResult);\n#endif // ENABLE_FOG\n\n#ifdef ENABLE_POINT_LIGHTS\n// multi-point-lights\nlowp vec3 CalculateLighting(vec3 fragPos, vec3 N);\n#endif // ENABLE_POINT_LIGHTS\n\nvoid main(void)\n{\n\t// Use normalisation cube map instead of normalize() - See section 3.3.1 of white paper for more info\n\t// Macbear note: no need at new hardward\n\t// - See section 6.5 of PowerVR SGX.OpenGL ES 2.0 Application Development Recommendations\n\t// lowp vec3 eyeToObjNormal = normalize(eyeToObj);\n\tlowp vec3 eyeToObjNormal = eyeToObj / eyeToObjDist; // as normalize: increase little FPS, but seem lost precision\n\t\n\t// When distortion is enabled, use the normal map to calculate perturbation\n\t// Same as * 2.0 - 1.0\n\tlowp vec3 vAccumulatedNormal = texture(NormalTex, BumpCoord0).rgb + texture(NormalTex, BumpCoord1).rgb - 1.0;\n\n\t// blend reflection and refraction\n\tlowp vec4 resultColor;\n\tresultColor = BlendReflectionRefraction(vAccumulatedNormal, eyeToObjNormal);\n\n#ifdef ENABLE_WATER_SPECULAR\n\t// specular part:\n\tmediump vec3 H = normalize(eyeToObjNormal + uLightDir);\n\tmediump float sf = max(0.0, dot(H, vAccumulatedNormal));\n//\tmediump float sf = clamp(dot(H, vAccumulatedNormal), 0.0, 1.0);\n\tsf = pow(sf, 120.0);\n\t\n\tlowp float fTemp = sf;\n//\tresultColor = vec4(LightDiffuse * fTemp, 1.0);\t\t// for debug purpose\n\tresultColor = vec4(resultColor.rgb + LightDiffuse * fTemp, 1.0);\n\t// resultColor = vec4(uColor, 1);\n#endif // ENABLE_WATER_SPECULAR\n\n#if defined(ENABLE_SHADOW_MAP) || defined(ENABLE_SHADOW_CSM)\n\tlowp float litFactor = ComputeShadowLitFactor();\n\tif (litFactor >= 1.0) {\n\t\tresultColor = ShadeLit(resultColor);\n\t} else if (litFactor <= 0.0) {\n\t\tresultColor = ShadeUnlit(resultColor);\n\t} else {\n\t\tresultColor = mix(ShadeUnlit(resultColor), ShadeLit(resultColor), litFactor);\n\t}\n#endif // ENABLE_SHADOW_MAP or ENABLE_SHADOW_CSM\n\n#ifdef ENABLE_POINT_LIGHTS\n\tresultColor.rgb += CalculateLighting(ObjectspaceV, vAccumulatedNormal) * 0.3;\n#endif\n\n#ifdef ENABLE_FOG\n\tresultColor = ApplyFog(resultColor);\n#endif // ENABLE_FOG\n\n\tfragColor = resultColor;\n}\n\n \n#version 300 es\n\n// uPointLights[0]\uff1alight0, light1\n// light0: col0: positionRange(xyz:pos,w:range), col1: colorIntensity(rgb:color,a:intensity)\n// light1: col2: positionRange(xyz:pos,w:range), col3: colorIntensity(rgb:color,a:intensity)\n// same for uPointLights[1,2,3]\n// uPointLights[1]\uff1alight2, light3\n// uPointLights[2]\uff1alight4, light5\n// uPointLights[3]\uff1alight6, light7\nuniform mediump mat4 uPointLights[4];\n\nuniform mediump ivec2 uPointLightCounts; // x=lightCount, y=shadowCastingCount\n\n// UE4 windowed inverse-square attenuation (Karis 2013)\n// +1.0 \u907f\u514d\u5149\u6e90\u8fd1\u8ddd\u96e2\u904e\u66dd/firefly\uff0crangeFade \u8b93\u5149\u7167\u5728 radius \u908a\u754c\u5e73\u6ed1\u6b78\u96f6\nfloat calcAttenuation(float distSq, float radiusSq) {\n    float ratio = distSq / radiusSq;\n    float rangeFade = clamp(1.0 - ratio * ratio, 0.0, 1.0);\n    return (rangeFade * rangeFade) / (distSq + 1.0);\n}\n\nvec3 calcPointLight(int i, vec3 fragPos, vec3 N, bool castShadow) {\n    int matIndex = i / 2;      // \u54ea\u500b mat4\n    int localIndex = i % 2;    // \u8a72 mat4 \u88e1\u7684\u7b2c\u5e7e\u76de\u71c8\n\n    mat4 m = uPointLights[matIndex];\n    vec4 positionRangeSq = localIndex == 0 ? m[0] : m[2];\n    vec4 colorIntensity = localIndex == 0 ? m[1] : m[3];\n\n    vec3 lightPos = positionRangeSq.xyz;\n    float radiusSq = positionRangeSq.w;\n\n    vec3 L = lightPos - fragPos;\n    L *= uInvObjScale;\n    float distSq = dot(L, L);          // \u7528\u5b83\u7b97\u8ddd\u96e2\u5e73\u65b9\n    L = L * inversesqrt(max(distSq, 0.0001)); // \u5c31\u5730 normalize\uff0c\u8986\u5beb\u6210\u55ae\u4f4d\u5411\u91cf\n\n    float atten = calcAttenuation(distSq, radiusSq);\n    float NdotL = max(dot(N, L), 0.0);\n\n    // colorIntensity: rgb -> lightColor, a -> lightIntensity\n    vec3 radiance = colorIntensity.rgb * colorIntensity.a * atten * NdotL;\n\n    if (castShadow) {\n        // TODO: DPSM shadow lookup \u63a5\u9032\u4f86\n        // float shadow = sampleDPSMShadow(i, fragPos, lightPos);\n        // radiance *= shadow;\n    }\n\n    return radiance;\n}\n\n// point lights lighting in object space\nlowp vec3 CalculateLighting(vec3 fragPos, vec3 N) {\n    vec3 result = vec3(0.0);\n    int lightCount = uPointLightCounts.x;\n    int shadowCount = uPointLightCounts.y;\n\n    for (int i = 0; i < lightCount; i++) {\n        bool castShadow = i < shadowCount;\n        result += calcPointLight(i, fragPos, N, castShadow);\n    }\n    return result;\n}\n\n",B.aj)
